},
["GameObject-613823"] = {
["Text"] = {
["enUS"] = {
{
["Page"] = 1,
["Text"] = "<This ancient runestone has a carving of several haranir standing on a forested mountain. They look below at another group of haranir following a ball that radiates wave-like energy. The ball is taking them deep underground to a cave filled with many roots.\r\n\r\nThis carving appears to depict a split within the Haranir society, leading to one group staying on the surface, while the other takes the journey to Harandar.>",
},
},
},
["Title"] = {
["enUS"] = "Ancient Runestone",
},
["Source"] = {
["ID"] = 613823,
["Type"] = "GameObject",
},
},
["GameObject-579239"] = {
["Text"] = {
["enUS"] = {
{
["Page"] = 1,
["Text"] = "Aln'hara is no longer in Harandar, but her song remains. It is ingrained through every inch of the land and every beast within it.",
},
{
["Page"] = 2,
["Text"] = "The haranir were called to this land to keep it safe until she returns, and to renew the song. So we tend this land and wait.",
},
},
},
["Title"] = {
["enUS"] = "Seeker's Trail--Part 1: Call of Aln'hara",
},
["Source"] = {
["ID"] = 579239,
["Type"] = "GameObject",
},
},
["GameObject-290694"] = {
["Text"] = {
["enUS"] = {
{
["Page"] = 1,
["Text"] = "HERE LIES -\r\nZanazal the Wise, born to rule, beset by enemies, and resilient enough to endure a civil war that few others did. Though he never saw the others as his equal, he nevertheless saw the value in keeping his enemies close.",
},
},
},
["Title"] = {
["enUS"] = "Placard",
},
