[235392] = {
["BroadcastText"] = {
["enUS"] = {
["Ah, what a delectable aroma of violence you carry."] = true,
["This is a delicate art. Your labor will imbue the blade with the energy of your very soul."] = true,
["Ah, the ethereals. It was not so long ago that Xal'atath brought them into the fold."] = true,
["You stand upon a land ruled by predation. Here, the strong thrive and the weak sustain them."] = true,
["Darkness. Endless, yawning, monotonous darkness."] = true,
["The recent arrival of Xal'atath was, for a time, an entertaining shake up. But her vision for your world--for all of our cosmos--is terribly dull."] = true,
["That's what she told Salhadaar. Perhaps it was even the truth."] = true,
["But of course, it is the right of the victor to take from the defeated. On this world, and on every other."] = true,
["Is this what you mortals call... friendship? I hope so."] = true,
["I hunger for the opportunity to work together again. Come, let us forge a weapon worthy of your allies."] = true,
["Strangely, I find myself wanting to know you better. And I want you to know me."] = true,
["Speak to me when you are ready. I am eager to impress you."] = true,
},
},
["Name"] = {
["enUS"] = "Decimus",
},
},
