[241696] = {
["BroadcastText"] = {
["enUS"] = {
["We still bear the scars from the previous Lich King, death knight."] = true,
["You test my patience with your demonic fiends, warlock."] = true,
["Perhaps this is a new start of our city's story with death knights like yourself."] = true,
["Your demonic fiends will not save you, warlock."] = true,
["Perhaps you are free of the Lich King's darkness, death knight."] = true,
["You toy with the Light, draenei."] = true,
["Do not flaunt your demonic pets around us, warlock."] = true,
["Come to show how you know more of the Light than us, draenei?"] = true,
["The nearby guard glares at you and the void energy that you surround yourself with."] = true,
["You aided us in our time of need, death knight. You are... appreciated."] = true,
["I remember the Lich King's march on our city. Every moment of it."] = true,
["You test the good will of Silvermoon with your demonic ways, warlock."] = true,
["Silvermoon was saved despite the recklessness of another draenei wielding the Light."] = true,
["You are accepted into our city, death knight, after all you have done."] = true,
["Know your presence is barely tolerated, death knight."] = true,
["Where is your dark master, death knight?"] = true,
},
},
