[236144] = {
["BroadcastText"] = {
["enUS"] = {
["About your grandfather, Zul'jin?"] = true,
["Zul'jarra, I see that something is burdening you. I genuinely want to help."] = true,
["Rage is a powerful emotion. My people were once consumed by it as well."] = true,
["You seem... pensive, Zul'jarra. Are you not relieved Akil'zon graced us with her favor?"] = true,
["I was consumed by rage at Zul'jin for what he did and sought retribution against him for years."] = true,
},
