[119100] = {
["Name"] = {
["enUS"] = "Golgranoth",
},
},
[240240] = {
["BroadcastText"] = {
["enUS"] = {
["What if I promised that my task would take you far away from here?"] = true,
["To Light's Hope to gather relics and inspire the Vanguard."] = true,
["Well, I think you're absolutely right. I really did make a mess of it all, didn't I?"] = true,
["You're creating a bigger cloud with your moping than Xal'atath's Voidstorm."] = true,
["So you blame the Light, not your father?"] = true,
["Hmmph. Those defenders have exhausted themselves, giving of their own faith and power. We bolster their reserves."] = true,
["Speak your mind! Let it out before these feelings create a well of poison in your gut."] = true,
},
},
["Name"] = {
["enUS"] = "Alonsus Faol",
},
},
[258671] = {
