[264065] = {
["BroadcastText"] = {
["enUS"] = {
["But when King Anasterian fell, the Omnium shut down--not even Kael'thas knew how to revive it."] = true,
["Then if it was still dormant when you recovered it, could it somehow have been damaged before the King was slain?"] = true,
["So why is it active now? And what's causing it to malfunction? Do you think Kael'thas--"] = true,
["And I will search Dawnstar Spire to find the missing piece. Join me when you can, $PLAYER_NAME$. And Rommath, good luck."] = true,
["If I can find the missing component Dar'Khan ripped from the Omnium, will you be able to recalibrate and stabilize it?"] = true,
["There was much carnage that day, Rommath. Perhaps these anomalies can tell us more."] = true,
},
},
["Name"] = {
["enUS"] = "Magister Umbric",
},
},
[1112] = {
["Name"] = {
["enUS"] = "Leech Widow",
