[245646] = {
["BroadcastText"] = {
["enUS"] = {
["We have different goals for de Amani. Zul'jarra focuses on growing and preserving de Amani tribes within Zul'Aman."] = true,
["They abandoned us. They. Abandoned. Us. How do we know they won't do it again?"] = true,
["I see your eyes are widening, \"hash'ura.\" You're right. Forget what I have said. We have won. Zul'jarra has won."] = true,
["When Mor'duun came, I saw my vision of de Amani coming to life. With de lightwood, we would conquer de Twilight's Blade and then Eversong."] = true,
["De loa say our grandfather, de great Zul'jin, betrayed them. But why believe them? Or my dotterin' uncle. Or any gokinye?"] = true,
["I will go back to de village and celebrate with my sister."] = true,
["We were young when our mother died. My sister held de tribes together with de force of her will--without de loa."] = true,
["I could never be de warrior that Zul'jarra is. I talk my way through problems. She plows through them head on."] = true,
["I see de strength of the Amani--our tribe. We should conquer those around us! Zul'jarra doesn't understand."] = true,
["Zul'jarra could not see my vision, but I saw no other way. De loa? Feh."] = true,
},
